from inirules import parse


def test_sections_and_keys():
    got = parse("[a]\nx = 1\ny = 2\n")
    assert got == {"": {}, "a": {"x": "1", "y": "2"}}


def test_root_keys():
    got = parse("k = v\n[s]\na = b\n")
    assert got == {"": {"k": "v"}, "s": {"a": "b"}}


def test_simple_values():
    got = parse("k =   v   \ne =\n")
    assert got == {"": {"k": "v", "e": ""}}
